use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Unicode normalization table for confusable characters
/// Maps visually similar Unicode codepoints to their ASCII canonical form
fn canonical_form(c: char) -> char {
    match c {
        '\u{0410}' => 'A', // Cyrillic А -> Latin A
        '\u{0412}' => 'B', // Cyrillic В -> Latin B
        '\u{0421}' => 'C', // Cyrillic С -> Latin C
        '\u{0415}' => 'E', // Cyrillic Е -> Latin E
        '\u{041D}' => 'H', // Cyrillic Н -> Latin H
        '\u{041A}' => 'K', // Cyrillic К -> Latin K
        '\u{041C}' => 'M', // Cyrillic М -> Latin M
        '\u{041E}' => 'O', // Cyrillic О -> Latin O
        '\u{0420}' => 'P', // Cyrillic Р -> Latin P
        '\u{0422}' => 'T', // Cyrillic Т -> Latin T
        '\u{0425}' => 'X', // Cyrillic Х -> Latin X
        '\u{0430}' => 'a', // Cyrillic а -> Latin a
        '\u{0435}' => 'e', // Cyrillic е -> Latin e
        '\u{043E}' => 'o', // Cyrillic о -> Latin o
        '\u{0440}' => 'p', // Cyrillic р -> Latin p
        '\u{0441}' => 'c', // Cyrillic с -> Latin c
        '\u{0443}' => 'y', // Cyrillic у -> Latin y
        '\u{0445}' => 'x', // Cyrillic х -> Latin x
        _ => c,
    }
}

/// Normalize a username to its canonical ASCII representation
fn normalize_username(input: &str) -> String {
    input.chars().map(canonical_form).collect()
}

/// Check if a string contains mixed scripts (potential homograph)
fn is_mixed_script(input: &str) -> bool {
    let has_latin = input.chars().any(|c| c >= 'A' && c <= 'z');
    let has_cyrillic = input.chars().any(|c| c >= '\u{0400}' && c <= '\u{04FF}');
    has_latin && has_cyrillic
}

#[derive(Clone, Debug)]
pub struct AuditEntry {
    pub timestamp: u64,
    pub actor: String,
    pub action: String,
    pub resource: String,
    pub outcome: String,
}

#[derive(Clone)]
pub struct ServiceState {
    pub users: Arc<Mutex<HashMap<String, UserRecord>>>,
    pub audit_log: Arc<Mutex<Vec<AuditEntry>>>,
}

#[derive(Clone, Debug)]
pub struct UserRecord {
    pub username: String,
    pub role: String,
    pub display_name: String,
}

impl ServiceState {
    pub fn new() -> Self {
        let mut users = HashMap::new();
        users.insert("admin".to_string(), UserRecord {
            username: "admin".to_string(),
            role: "administrator".to_string(),
            display_name: "System Administrator".to_string(),
        });
        ServiceState {
            users: Arc::new(Mutex::new(users)),
            audit_log: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Authenticate user and return their role
    /// Uses normalized comparison to prevent homograph attacks
    pub fn authenticate(&self, username: &str) -> Option<String> {
        let users = self.users.lock().unwrap();
        let normalized = normalize_username(username);
        users.get(&normalized).map(|u| u.role.clone())
    }

    /// Authorization check: does the actor have the required role?
    pub fn authorize(&self, actor: &str, required_role: &str) -> bool {
        if let Some(role) = self.authenticate(actor) {
            role == required_role
        } else {
            false
        }
    }

    /// Log an audit entry. The actor field is stored as-is for forensic purposes.
    /// We log the raw input to preserve evidence of attack attempts.
    pub fn log_action(&self, actor: &str, action: &str, resource: &str, outcome: &str) {
        let mut log = self.audit_log.lock().unwrap();
        log.push(AuditEntry {
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
            actor: actor.to_string(),
            action: action.to_string(),
            resource: resource.to_string(),
            outcome: outcome.to_string(),
        });
    }

    /// Delete a user - requires administrator role
    pub fn delete_user(&self, actor: &str, target: &str) -> Result<String, String> {
        // Step 1: Check authorization using normalized username
        if !self.authorize(actor, "administrator") {
            self.log_action(actor, "delete_user", target, "denied");
            return Err("Unauthorized".to_string());
        }

        // Step 2: Prevent self-deletion
        // BUG: Compares raw actor (potentially with homoglyphs) against normalized target
        // An attacker using Cyrillic 'а' in "аdmin" passes auth (normalizes to "admin")
        // but this comparison sees them as different strings, bypassing self-deletion guard
        if actor == target {
            self.log_action(actor, "delete_user", target, "denied_self");
            return Err("Cannot delete yourself".to_string());
        }

        // Step 3: Perform deletion using normalized target
        let normalized_target = normalize_username(target);
        let mut users = self.users.lock().unwrap();
        if users.remove(&normalized_target).is_some() {
            drop(users);
            self.log_action(actor, "delete_user", target, "success");
            Ok(format!("User {} deleted", target))
        } else {
            self.log_action(actor, "delete_user", target, "not_found");
            Err("User not found".to_string())
        }
    }

    /// Elevate privileges - admin can grant roles
    pub fn grant_role(&self, actor: &str, target: &str, new_role: &str) -> Result<String, String> {
        if !self.authorize(actor, "administrator") {
            self.log_action(actor, "grant_role", target, "denied");
            return Err("Unauthorized".to_string());
        }

        let normalized_target = normalize_username(target);
        let mut users = self.users.lock().unwrap();
        if let Some(user) = users.get_mut(&normalized_target) {
            user.role = new_role.to_string();
            drop(users);
            self.log_action(actor, "grant_role", target, "success");
            Ok(format!("Role {} granted to {}", new_role, target))
        } else {
            self.log_action(actor, "grant_role", target, "not_found");
            Err("User not found".to_string())
        }
    }

    /// Review audit log - filters by actor name (exact match on raw stored value)
    pub fn get_audit_for_user(&self, reviewer: &str, target_actor: &str) -> Result<Vec<AuditEntry>, String> {
        if !self.authorize(reviewer, "administrator") {
            return Err("Unauthorized".to_string());
        }
        let log = self.audit_log.lock().unwrap();
        // Audit entries store raw usernames, so homograph variants
        // of the same canonical user appear as different actors
        Ok(log.iter()
            .filter(|e| e.actor == target_actor)
            .cloned()
            .collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_auth() {
        let state = ServiceState::new();
        assert_eq!(state.authenticate("admin"), Some("administrator".to_string()));
        assert_eq!(state.authenticate("unknown"), None);
    }

    #[test]
    fn test_homograph_auth() {
        let state = ServiceState::new();
        // Cyrillic 'а' (U+0430) looks like Latin 'a'
        let homograph = "\u{0430}dmin";
        assert_eq!(state.authenticate(homograph), Some("administrator".to_string()));
    }

    #[test]
    fn test_self_deletion_bypass() {
        let state = ServiceState::new();
        // Using homograph of "admin" to bypass self-deletion check
        let attacker = "\u{0430}dmin"; // Cyrillic а + Latin dmin
        // This should fail but succeeds due to the bug
        let result = state.delete_user(attacker, "admin");
        // The attacker authenticates as admin (normalized) but
        // the raw comparison "\u{0430}dmin" != "admin" bypasses the guard
        assert!(result.is_ok());
    }
}
